-- Wording: "Freshmen" -> "Freshers" (and "freshman" -> "fresher") in the content
-- students read: the guide, its FAQs and KNH Hub posts. Whole words only --
-- image paths, links and file names (e.g. uploads under freshmen/) are left
-- untouched. Table and column names stay as they are. Safe to re-run.

UPDATE freshmen_guides SET
  title = REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(title, '(?<![/\\w-])FRESHMEN(?![/\\w-]|\\.\\w)', 'FRESHERS', 1, 0, 'c'), '(?<![/\\w-])Freshmen(?![/\\w-]|\\.\\w)', 'Freshers', 1, 0, 'c'), '(?<![/\\w-])freshmen(?![/\\w-]|\\.\\w)', 'freshers', 1, 0, 'c'), '(?<![/\\w-])FRESHMAN(?![/\\w-]|\\.\\w)', 'FRESHER', 1, 0, 'c'), '(?<![/\\w-])Freshman(?![/\\w-]|\\.\\w)', 'Fresher', 1, 0, 'c'), '(?<![/\\w-])freshman(?![/\\w-]|\\.\\w)', 'fresher', 1, 0, 'c'),
  summary = REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(summary, '(?<![/\\w-])FRESHMEN(?![/\\w-]|\\.\\w)', 'FRESHERS', 1, 0, 'c'), '(?<![/\\w-])Freshmen(?![/\\w-]|\\.\\w)', 'Freshers', 1, 0, 'c'), '(?<![/\\w-])freshmen(?![/\\w-]|\\.\\w)', 'freshers', 1, 0, 'c'), '(?<![/\\w-])FRESHMAN(?![/\\w-]|\\.\\w)', 'FRESHER', 1, 0, 'c'), '(?<![/\\w-])Freshman(?![/\\w-]|\\.\\w)', 'Fresher', 1, 0, 'c'), '(?<![/\\w-])freshman(?![/\\w-]|\\.\\w)', 'fresher', 1, 0, 'c')
WHERE title LIKE '%reshm%' OR summary LIKE '%reshm%';

